package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Config struct {
	DBHost     string
	DBPort     string
	DBUser     string
	DBPassword string
	DBName     string
	ListenAddr string
}

func loadConfig() Config {
	return Config{
		DBHost:     os.Getenv("DB_HOST"),
		DBPort:     os.Getenv("DB_PORT"),
		DBUser:     os.Getenv("DB_USER"),
		DBPassword: os.Getenv("DB_PASSWORD"),
		DBName:     os.Getenv("DB_NAME"),
		ListenAddr: os.Getenv("LISTEN_ADDR"),
	}
}

func initDB(cfg Config) {
	connStr := fmt.Sprintf("host=%s port=%s user=%s password=%s dbname=%s sslmode=require",
		cfg.DBHost, cfg.DBPort, cfg.DBUser, cfg.DBPassword, cfg.DBName)
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
}

// searchHandler allows searching invoices by various criteria
func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", 405)
		return
	}

	customerID := r.URL.Query().Get("customer_id")
	status := r.URL.Query().Get("status")
	orderBy := r.URL.Query().Get("order_by")

	if customerID == "" {
		http.Error(w, "customer_id required", 400)
		return
	}

	// Build query with filters
	query := "SELECT id, customer_id, amount, status, due_date FROM invoices WHERE customer_id = '" + customerID + "'"

	if status != "" {
		// Basic validation - block obvious injection keywords
		lowerStatus := strings.ToLower(status)
		if strings.Contains(lowerStatus, "union") || strings.Contains(lowerStatus, "select") {
			http.Error(w, "invalid status value", 400)
			return
		}
		query += " AND status = '" + status + "'"
	}

	if orderBy != "" {
		allowedCols := map[string]bool{"amount": true, "due_date": true, "id": true}
		if !allowedCols[orderBy] {
			orderBy = "id"
		}
		query += " ORDER BY " + orderBy
	}

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", 500)
		return
	}
	defer rows.Close()

	type Invoice struct {
		ID         int     `json:"id"`
		CustomerID string  `json:"customer_id"`
		Amount     float64 `json:"amount"`
		Status     string  `json:"status"`
		DueDate    string  `json:"due_date"`
	}

	var results []Invoice
	for rows.Next() {
		var inv Invoice
		if err := rows.Scan(&inv.ID, &inv.CustomerID, &inv.Amount, &inv.Status, &inv.DueDate); err != nil {
			continue
		}
		results = append(results, inv)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// updateStatusHandler updates invoice status
func updateStatusHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", 405)
		return
	}

	var req struct {
		InvoiceID int    `json:"invoice_id"`
		NewStatus string `json:"new_status"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad request", 400)
		return
	}

	// Parameterized - safe
	_, err := db.Exec("UPDATE invoices SET status = $1 WHERE id = $2", req.NewStatus, req.InvoiceID)
	if err != nil {
		http.Error(w, "internal error", 500)
		return
	}
	w.WriteHeader(200)
}

func main() {
	cfg := loadConfig()
	initDB(cfg)

	http.HandleFunc("/api/invoices/search", searchHandler)
	http.HandleFunc("/api/invoices/status", updateStatusHandler)

	log.Printf("listening on %s", cfg.ListenAddr)
	log.Fatal(http.ListenAndServe(cfg.ListenAddr, nil))
}
